export function getLocation() {
    return data;
}

export function getLocationByName(location) {
    const normalized = location?.trim().toLowerCase();
    return (
        data.find((item) => item.location.toLowerCase() === normalized) || {
            location: "",
            latitude: "",
            longitude: "",
        }
    );
}
